parameters.jsCode:
// Sanitasi dan validasi data lead dummy masuk
const input = $json.body || $json;

const fullName = (input.full_name || 'Budi Santoso').trim();
const email = (input.email || 'budi.santoso@startupindonesia.co.id').toLowerCase();
const company = input.company || 'PT Solusi Bangun Digital';
const budgetUsd = Number(input.budget_usd) || 3500;
const message = input.message || 'Kami butuh integrasi automasi database CRM ke WhatsApp API dan Telegram dalam 2 minggu.';

// Evaluasi awal
const isCorporateEmail = !email.endsWith('@gmail.com') && !email.endsWith('@yahoo.com');
const preliminaryScore = budgetUsd >= 3000 ? 85 : 50;

return [{
  json: {
    lead_id: 'LEAD-' + Math.floor(100000 + Math.random() * 900000),
    full_name: fullName,
    email: email,
    company: company,
    budget_usd: budgetUsd,
    is_corporate: isCorporateEmail,
    preliminary_score: preliminaryScore,
    raw_message: message,
    submitted_at: new Date().toISOString()
  }
}];

